Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
using namespace std;
#define sz(a) ((int)(a).size())
#define null NULL
#define mp make_pair
#define fi first
#define se second
#define pb push_back
#define all(a) (a).begin(), (a).end()
#define relaxMin(a, b) (a) = min((a), (b))
#define relaxMax(a, b) (a) = max((a), (b))
#define PI 3.1415926535897932384
typedef long long ll;
typedef vector<int> vi;
typedef pair<int, int> pii;

#define BITS(a) __builtin_popcount(a)
const double EPS = 1E-9;

typedef long double dbl;

typedef pair<dbl, dbl> Val; // a * fi + se

Val Add(const Val& f, const Val& s){
  return mp(f.fi + s.fi,
            f.se + s.se);
}

Val Sub(const Val& f, const Val& s){
  return mp(f.fi - s.fi,
            f.se - s.se);
}

Val Mult(const Val& f, dbl w){
  return mp(f.fi * w,
            f.se * w);
}

Val Div(const Val& f, dbl w){
  return mp(f.fi / w,
            f.se / w);
}

Val dp[1 << 20];
int n, k;
double p[25];

double Solve(int vr){
  if(p[vr] < EPS) return 0.0;

  dp[0] = Val(1.0, 0.0);
  for(int msk = 1;msk < (1 << n);++msk){
    if(msk & (1 << vr)) continue;
    //Val ri = Mult(Val(1.0, 0.0), p[vr]);
    Val ri(0.0, 0.0);
    dbl same = 0.0;

    for(int i = 0;i < n;++i)
      if(i != vr)
        if(msk & (1 << i)){
          same += p[i];
          ri = Add(ri, Mult(dp[msk ^ (1 << i)], p[i]));
        }

    //cout << ri.fi << ' ' << ri.s << endl;
    dp[msk] = Div(ri, 1.0 - same);
  }

  //cout << dp[2].fi << ' ' << dp[2].se << endl;

  Val tot(1.0, 0.0);
  for(int msk = 1;msk < (1 << n);++msk)
    if(!(msk & (1 << vr))){
      tot = Add(tot, dp[msk]);
    }

  dbl alp = (1.0 - tot.se) / tot.fi;

  Val bad(0.0, 0.0);
  for(int msk = 0;msk < (1 << n);++msk){
    if(msk & (1 << vr)) continue;
    if(BITS(msk) >= k) bad = Add(bad, dp[msk]);
  }

  return 1.0 - (alp * bad.fi + bad.se);
}

int main(){
  scanf("%d%d", &n, &k);
  for(int i = 0;i < n;++i)
    scanf("%lf", &p[i]);

  for(int i = 0;i < n;++i)
    printf("%.12f%c", Solve(i), (i + 1 == n ? '\n' : ' '));

  return 0;
}


